window.SIM_DATA = {"id":"tp5-vpn-ipsec","w":1242,"h":1060,"images":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"slides":[{"img":0,"step":"Introduction","text":"TP5 – VPN IPsec site à site entre R1 et R3 à travers R2. Écrans reconstitués : résultats attendus.","kind":"show","dur":9380},{"img":1,"step":"Adressage et routage","text":"R1 : Fa0/0 192.168.1.1/24, S1/0 10.1.1.2/30, route par défaut vers R2. R2 et R3 sont configurés selon la table d'adressage.","kind":"show","dur":10880},{"img":2,"step":"Adressage et routage","text":"Adressez PC-A : IP, masque et passerelle.","kind":"type","x":56.0,"answers":["ip 192.168.1.3 255.255.255.0 192.168.1.1","ip 192.168.1.3/24 192.168.1.1","ip 192.168.1.3 /24 192.168.1.1"]},{"img":3,"step":"Adressage et routage","text":"Testez la connectivité PC-A → PC-C avant le VPN.","kind":"type","x":56.0,"answers":["ping 192.168.3.3"]},{"img":4,"step":"Adressage et routage","text":"Succès (TTL 61 : 3 routeurs). Mais le trafic circule EN CLAIR à travers R2.","kind":"show","dur":8000},{"img":5,"step":"IKE phase 1","text":"Activez ISAKMP (UDP 500), utilisé par IKE pour négocier les SA.","kind":"type","x":96.0,"answers":["crypto isakmp enable"]},{"img":6,"step":"IKE phase 1","text":"ACL 110 : le trafic intéressant (LAN R1 → LAN R3) qui sera chiffré.","kind":"type","x":96.0,"answers":["access-list 110 permit ip 192.168.1.0 0.0.0.255 192.168.3.0 0.0.0.255"]},{"img":7,"step":"IKE phase 1","text":"Créez la politique IKE phase 1 de priorité 10.","kind":"type","x":96.0,"answers":["crypto isakmp policy 10"]},{"img":8,"step":"IKE phase 1","text":"Chiffrement AES du canal de négociation.","kind":"type","x":151.0,"answers":["encryption aes"]},{"img":9,"step":"IKE phase 1","text":"Authentification par clé pré-partagée.","kind":"type","x":151.0,"answers":["authentication pre-share"]},{"img":10,"step":"IKE phase 1","text":"Diffie-Hellman groupe 2 (1024 bits). Hachage SHA et durée 86400 s sont par défaut.","kind":"type","x":151.0,"answers":["group 2"]},{"img":11,"step":"IKE phase 1","text":"Clé pré-partagée « cisco » pour le pair R3 (10.2.2.2).","kind":"type","x":96.0,"answers":["crypto isakmp key cisco address 10.2.2.2"]},{"img":12,"step":"IKE phase 2","text":"Transform-set de phase 2 : ESP chiffré 3DES + intégrité SHA-HMAC.","kind":"type","x":96.0,"answers":["crypto ipsec transform-set VPN-SET esp-3des esp-sha-hmac"]},{"img":13,"step":"IKE phase 2","text":"Créez la crypto map (séquence 10, établie par IKE).","kind":"type","x":96.0,"answers":["crypto map VPN-MAP 10 ipsec-isakmp"]},{"img":14,"step":"IKE phase 2","text":"Indiquez le pair distant R3.","kind":"type","x":182.0,"answers":["set peer 10.2.2.2"]},{"img":15,"step":"IKE phase 2","text":"Associez le transform-set.","kind":"type","x":182.0,"answers":["set transform-set VPN-SET"]},{"img":16,"step":"IKE phase 2","text":"Associez l'ACL du trafic à chiffrer.","kind":"type","x":182.0,"answers":["match address 110"]},{"img":17,"step":"IKE phase 2","text":"Appliquez la crypto map sur l'interface de sortie S1/0.","kind":"type","x":119.0,"answers":["crypto map VPN-MAP"]},{"img":18,"step":"IKE phase 2","text":"R1 prêt. Configuration symétrique sur R3 : ACL miroir (192.168.3.0 → 192.168.1.0), pair 10.1.1.2, crypto map sur S1/1.","kind":"show","dur":10580},{"img":19,"step":"Avant le trafic","text":"Vérifiez l'état du tunnel avant tout trafic.","kind":"type","x":33.0,"answers":["show crypto ipsec sa","sh crypto ipsec sa"]},{"img":20,"step":"Avant le trafic","text":"pkts encaps/encrypt et decaps/decrypt = 0, aucune SA ESP : le tunnel ne se monte qu'à la demande.","kind":"show","dur":9320},{"img":21,"step":"Trafic et vérification","text":"Avant le trafic : dans GNS3, clic droit sur le lien R1 – R2 → Start capture (Cisco HDLC). Wireshark s'ouvre.","kind":"show","dur":9980},{"img":22,"step":"Trafic et vérification","text":"Capture en cours : seulement les keepalives SLARP et CDP du lien série. Aucun trafic IPsec pour l'instant.","kind":"show","dur":9860},{"img":23,"step":"Trafic et vérification","text":"Générez du trafic intéressant : ping PC-A → PC-C.","kind":"type","x":56.0,"answers":["ping 192.168.3.3"]},{"img":24,"step":"Trafic et vérification","text":"1er paquet perdu pendant la négociation IKE (Main Mode puis Quick Mode), puis le trafic passe dans le tunnel.","kind":"show","dur":10040},{"img":25,"step":"Trafic et vérification","text":"Vérifiez la SA de phase 1.","kind":"type","x":33.0,"answers":["show crypto isakmp sa","sh crypto isakmp sa"]},{"img":26,"step":"Trafic et vérification","text":"Phase 1 ACTIVE (QM_IDLE). Réaffichez les SA IPsec.","kind":"type","x":33.0,"answers":["show crypto ipsec sa","sh crypto ipsec sa"]},{"img":27,"step":"Trafic et vérification","text":"encaps/encrypt = 4 et decaps/decrypt = 4 ; SA ESP entrante et sortante ACTIVE (esp-3des esp-sha-hmac, mode Tunnel).","kind":"show","dur":10400},{"img":28,"step":"Analyse Wireshark","text":"Dans Wireshark, affichez la négociation IKE : tapez le filtre isakmp, puis Entrée.","kind":"type","box":[34.0,166.0,1150.0,22.0],"answers":["isakmp"]},{"img":29,"step":"Analyse Wireshark","text":"9 messages ISAKMP (UDP 500) entre 10.1.1.2 et 10.2.2.2 : 6 en Main Mode (IKE phase 1), puis 3 en Quick Mode (phase 2).","kind":"show","dur":10580},{"img":30,"step":"Analyse Wireshark","text":"Cherchez maintenant les pings de PC-A : tapez le filtre icmp, puis Entrée.","kind":"type","box":[34.0,166.0,1150.0,22.0],"answers":["icmp"]},{"img":31,"step":"Analyse Wireshark","text":"Displayed: 0 ! Les pings 192.168.1.3 → 192.168.3.3 sont passés, mais ils sont chiffrés : Wireshark ne voit aucun ICMP.","kind":"show","dur":10580},{"img":32,"step":"Analyse Wireshark","text":"Affichez le trafic chiffré : tapez le filtre esp, puis Entrée.","kind":"type","box":[34.0,166.0,1150.0,22.0],"answers":["esp"]},{"img":33,"step":"Analyse Wireshark","text":"8 paquets ESP (protocole 50) : 4 échos chiffrés de R1 vers R3 et 4 réponses. Le 1er ping, perdu pendant IKE, n'apparaît pas.","kind":"show","dur":10940},{"img":34,"step":"Analyse Wireshark","text":"Sélectionnez le premier paquet ESP (10.1.1.2 → 10.2.2.2).","kind":"click","box":[0.0,212.0,1242.0,18.0],"hint":"Cliquez sur la première ligne ESP (10.1.1.2 → 10.2.2.2)"},{"img":35,"step":"Analyse Wireshark","text":"Nouvel en-tête IP : 10.1.1.2 → 10.2.2.2 (adresses des pairs), puis l'en-tête ESP. Aucune trace des adresses 192.168.x.x.","kind":"show","dur":10700},{"img":36,"step":"Analyse Wireshark","text":"Dépliez l'en-tête ESP.","kind":"click","box":[0.0,530.0,1242.0,18.0],"hint":"Cliquez sur la ligne « Encapsulating Security Payload »"},{"img":37,"step":"Analyse Wireshark","text":"SPI 0x8b3a51c2 = SA sortante de R1 (show crypto ipsec sa) ; séquence 1 (anti-rejeu). Le reste est chiffré (3DES) et signé (SHA).","kind":"show","dur":11180},{"img":38,"step":"Fin","text":"Sur le lien R1–R2 : IP 10.1.1.2 → 10.2.2.2, protocole 50 (ESP) ; le paquet d'origine est chiffré et invisible.","kind":"show","dur":10100}]};
